import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Which customers a list shows: a name search and a set of statuses.
 *
 * <p>A customer matches when it satisfies both parts. The name is split on
 * whitespace into terms, and every term must appear in the customer's first name
 * or last name. Case and accents are ignored, so {@code makinen} finds
 * {@code Mäkinen}. An empty name matches every customer, and so does an empty
 * set of statuses.
 *
 * @param name     the text typed into the name search; may be empty
 * @param statuses the statuses to show; empty means every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("[\\s\\p{Z}]+");
    private static final Pattern ACCENTS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        EnumSet<CustomerStatus> chosen = EnumSet.noneOf(CustomerStatus.class);
        chosen.addAll(statuses);
        statuses = Collections.unmodifiableSet(chosen);
    }

    /**
     * Returns a test for whether a customer satisfies this filter. The name is
     * folded once, here, rather than once per customer.
     */
    public Predicate<Customer> toPredicate() {
        List<String> terms = nameTerms();
        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
                && nameMatches(customer, terms);
    }

    private List<String> nameTerms() {
        return WHITESPACE.splitAsStream(fold(name))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    private static boolean nameMatches(Customer customer, List<String> terms) {
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    /** Strips accents and lower-cases, so that {@code Mäkinen} and {@code makinen} compare equal. */
    private static String fold(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return ACCENTS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
